function piStoreApt(it) {
  var p = String((it && it.partner) || '').trim();
  if (p && !/^credit_note\b/i.test(p)) return p;
  var listing = String((it && it.listingName) || '').trim();
  if (listing) return listing;
  var parts = String((it && it.filename) || '').replace(/\\/g, '/').split('/');
  if (parts.length >= 3) {
    var folder = parts[parts.length - 2];
    if (folder && !/^\d{4}-\d{2}$/.test(folder) && !/^Airbnb$|^Booking/i.test(folder)) return folder;
  }
